import{_ as n,o as s,c as t,ag as e}from"./chunks/framework.DXGyWiRo.js";const p="/assets/james_gosling.okohIxPk.png",l="/assets/langs_rank.COfFyfZ0.png",d="/assets/jdk_compose.CTGzKfYl.png",g=JSON.parse('{"title":"概述与基础","description":"","frontmatter":{},"headers":[],"relativePath":"langs/java/02_base.md","filePath":"langs/java/02_base.md","lastUpdated":1780025083000}'),i={name:"langs/java/02_base.md"};function o(c,a,r,h,b,m){return s(),t("div",null,[...a[0]||(a[0]=[e('<h1 id="概述与基础" tabindex="-1">概述与基础 <a class="header-anchor" href="#概述与基础" aria-label="Permalink to &quot;概述与基础&quot;">​</a></h1><h2 id="java起源与发展" tabindex="-1">Java起源与发展 <a class="header-anchor" href="#java起源与发展" aria-label="Permalink to &quot;Java起源与发展&quot;">​</a></h2><p><img src="'+p+'" alt="James Gosling"></p><p>美国 · James Gosling，Java之父</p><p>Java语言于1995.5.23 由SUN公司正式发布</p><p>编程语言排行：<a href="https://www.tiobe.com/tiobe-index/" target="_blank" rel="noreferrer">https://www.tiobe.com/tiobe-index/</a></p><p><img src="'+l+'" alt="编程语言排行"></p><h3 id="java5的新功能" tabindex="-1">Java5的新功能 <a class="header-anchor" href="#java5的新功能" aria-label="Permalink to &quot;Java5的新功能&quot;">​</a></h3><ul><li>枚举类型</li><li>静态导入</li><li>增强的for循环</li><li>自动装箱/自动拆箱</li><li>可变参数的方法</li><li>泛型</li><li>注解</li></ul><h3 id="java7的新功能" tabindex="-1">Java7的新功能 <a class="header-anchor" href="#java7的新功能" aria-label="Permalink to &quot;Java7的新功能&quot;">​</a></h3><ul><li>二进制整数表示</li><li>在数值字面量中使用下划线</li><li>用String控制switch语句</li><li>菱形运算符</li><li>用一个catch捕获多个异常</li><li>使用try-with-resources实现自动资源管理</li></ul><h3 id="java8的新功能" tabindex="-1">Java8的新功能 <a class="header-anchor" href="#java8的新功能" aria-label="Permalink to &quot;Java8的新功能&quot;">​</a></h3><ul><li>Lambda表达式</li><li>接口的默认方法和静态方法</li><li>新的日期/时间API</li><li>集合的聚集操作</li><li>类型注解</li></ul><h3 id="java语言优点" tabindex="-1">Java语言优点 <a class="header-anchor" href="#java语言优点" aria-label="Permalink to &quot;Java语言优点&quot;">​</a></h3><ul><li>语法简单</li><li>面向对象</li><li>平台独立性、可移植性</li><li>健壮性、安全性</li><li>分布式、高性能</li><li>多线程、动态性</li></ul><h2 id="应用领域" tabindex="-1">应用领域 <a class="header-anchor" href="#应用领域" aria-label="Permalink to &quot;应用领域&quot;">​</a></h2><ul><li>企业服务端软件开发，90%以上</li><li>科学计算</li><li>大数据、云计算</li><li>移动开发</li><li>桌面应用开发</li><li>游戏开发</li></ul><h2 id="java平台与开发环境" tabindex="-1">Java平台与开发环境 <a class="header-anchor" href="#java平台与开发环境" aria-label="Permalink to &quot;Java平台与开发环境&quot;">​</a></h2><h3 id="三大版本" tabindex="-1">三大版本 <a class="header-anchor" href="#三大版本" aria-label="Permalink to &quot;三大版本&quot;">​</a></h3><p>Java标准版（Java Standard Edition，Java SE）</p><p>Java企业版（Java Enterprise Edition，Java EE）</p><p>Java微型版（Java Micro Edition，Java ME）</p><h3 id="jvm" tabindex="-1">JVM <a class="header-anchor" href="#jvm" aria-label="Permalink to &quot;JVM&quot;">​</a></h3><p>Java Virtual Machine，Java虚拟机。运行字节码。</p><h3 id="jre" tabindex="-1">JRE <a class="header-anchor" href="#jre" aria-label="Permalink to &quot;JRE&quot;">​</a></h3><p>Java Runtime Enviroment，Java运行时环境。 JVM和Java类库一起构成。</p><h3 id="jdk" tabindex="-1">JDK <a class="header-anchor" href="#jdk" aria-label="Permalink to &quot;JDK&quot;">​</a></h3><p>Java Development Toolkit，Java开发工具包。包括JRE，外加一个编译器和其他工具。</p><p><a href="https://docs.oracle.com/javase/8/docs/" target="_blank" rel="noreferrer">https://docs.oracle.com/javase/8/docs/</a></p><p><img src="'+d+`" alt="JDK"></p><p>Java是平台独立的，是跨平台的。传统的编程中，源代码要编译成可执行代码。</p><p>Java中，<strong>源代码</strong>被编译成<strong>字节码</strong>（bytecode），字节码需要在Java虚拟机（<strong>JVM</strong>）上运行。</p><p>Java成为一种跨平台的语言，进而实现“编写一次，到处运行”。</p><p><img src="http://www.kdocs.?" alt="img"></p><h3 id="jdk下载与安装" tabindex="-1">JDK下载与安装 <a class="header-anchor" href="#jdk下载与安装" aria-label="Permalink to &quot;JDK下载与安装&quot;">​</a></h3><p><a href="https://www.oracle.com/java/technologies/downloads/" target="_blank" rel="noreferrer">https://www.oracle.com/java/technologies/downloads/</a></p><p><img src="http://www.kdocs.?" alt="img"></p><h3 id="java-ide" tabindex="-1">Java IDE <a class="header-anchor" href="#java-ide" aria-label="Permalink to &quot;Java IDE&quot;">​</a></h3><h4 id="eclipse" tabindex="-1">Eclipse <a class="header-anchor" href="#eclipse" aria-label="Permalink to &quot;Eclipse&quot;">​</a></h4><p><a href="https://www.eclipse.org/downloads/packages/" target="_blank" rel="noreferrer">https://www.eclipse.org/downloads/packages/</a></p><p><img src="http://www.kdocs.?" alt="img"></p><h4 id="intellij-idea" tabindex="-1">Intellij IDEA <a class="header-anchor" href="#intellij-idea" aria-label="Permalink to &quot;Intellij IDEA&quot;">​</a></h4><p><a href="https://www.jetbrains.com/zh-cn/idea/download/?section=windows" target="_blank" rel="noreferrer">https://www.jetbrains.com/zh-cn/idea/download/?section=windows</a></p><p><img src="http://www.kdocs.?" alt="img"></p><p><em><strong>*IDEA开发步骤：*</strong></em></p><p>①new Empty Project</p><p>②new Module</p><p>③new Package</p><p>④new Class</p><p>⑤编写代码并运行</p><p>IDEA常用设置：字体、背景色、快捷键</p><h2 id="java程序基本结构" tabindex="-1">Java程序基本结构 <a class="header-anchor" href="#java程序基本结构" aria-label="Permalink to &quot;Java程序基本结构&quot;">​</a></h2><p><em><strong>*开发步骤：*</strong></em></p><ol><li>****编辑****源程序</li><li>****编译****源程序 <code>javac HelloWorld.java</code></li><li>****执行****程序 <code>java HelloWorld</code></li></ol><p>HelloWorld</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>public class HelloWorld {</span></span>
<span class="line"><span>    public static void main(String[] args){</span></span>
<span class="line"><span>        System.out.println(&quot;Hello world&quot;);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>****项目结构：****工程 Project、模块 Mudule、包 Package、类 Class</p><h3 id="编程要点" tabindex="-1">编程要点 <a class="header-anchor" href="#编程要点" aria-label="Permalink to &quot;编程要点&quot;">​</a></h3><ul><li>大小写敏感</li><li>类名，首字母大写</li><li>方法名，首字母小写</li><li>源文件名，和类名相同</li><li>程序入口：<code>***\\*public static void main(String[] args)\\****</code></li></ul><h2 id="代码风格与注释" tabindex="-1">代码风格与注释 <a class="header-anchor" href="#代码风格与注释" aria-label="Permalink to &quot;代码风格与注释&quot;">​</a></h2><h3 id="代码风格" tabindex="-1">代码风格 <a class="header-anchor" href="#代码风格" aria-label="Permalink to &quot;代码风格&quot;">​</a></h3><h4 id="缩进和空白" tabindex="-1">缩进和空白 <a class="header-anchor" href="#缩进和空白" aria-label="Permalink to &quot;缩进和空白&quot;">​</a></h4><p>代码缩进可清晰描述程序中各部分或语句之间的结构关系。</p><p>保持一致的缩进会使程序更加清晰、易读、易于调试和维护。</p><h4 id="代码块风格" tabindex="-1">代码块风格 <a class="header-anchor" href="#代码块风格" aria-label="Permalink to &quot;代码块风格&quot;">​</a></h4><p>代码块是由大括号围起来的一组语句，如类体、方法体、初始化块等。</p><p>ANSI/Allman/BSD风格</p><p>Kernighan_Ritchie风格</p><h3 id="java注释" tabindex="-1">Java注释 <a class="header-anchor" href="#java注释" aria-label="Permalink to &quot;Java注释&quot;">​</a></h3><p>注释是对程序功能的解释或说明，是为阅读和理解程序的功能提供方便。所有注释的内容都被编译器忽略。</p><h4 id="单行注释" tabindex="-1">单行注释 <a class="header-anchor" href="#单行注释" aria-label="Permalink to &quot;单行注释&quot;">​</a></h4><p>以双斜杠（//）开头，在该行的末尾结束</p><h4 id="多行注释" tabindex="-1">多行注释 <a class="header-anchor" href="#多行注释" aria-label="Permalink to &quot;多行注释&quot;">​</a></h4><p>以<code>/*</code>开始，以<code>*/</code>结束的一行或多行文字</p><h4 id="文档注释" tabindex="-1">文档注释 <a class="header-anchor" href="#文档注释" aria-label="Permalink to &quot;文档注释&quot;">​</a></h4><p>以/*<em>开始，以</em>/结束的多行</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 单行注释</span></span>
<span class="line"><span>/*</span></span>
<span class="line"><span>多</span></span>
<span class="line"><span>行</span></span>
<span class="line"><span>注</span></span>
<span class="line"><span>释</span></span>
<span class="line"><span>*/</span></span>
<span class="line"><span> </span></span>
<span class="line"><span>/**</span></span>
<span class="line"><span>文</span></span>
<span class="line"><span>档</span></span>
<span class="line"><span>注</span></span>
<span class="line"><span>释</span></span>
<span class="line"><span>*/</span></span></code></pre></div><p>文档注释生成：<code>javadoc -d 文件夹 -encoding UTF-8 Hellwold.java</code></p><h2 id="简单程序的开发" tabindex="-1">简单程序的开发 <a class="header-anchor" href="#简单程序的开发" aria-label="Permalink to &quot;简单程序的开发&quot;">​</a></h2><h3 id="变量与赋值" tabindex="-1">变量与赋值 <a class="header-anchor" href="#变量与赋值" aria-label="Permalink to &quot;变量与赋值&quot;">​</a></h3><p>变量（variable）用于在程序中临时存放数据。</p><p>Java有两大类型的变量：</p><ol><li>基本类型的变量：数值型（整数型和浮点型）、布尔型和字符型。</li><li>引用类型的变量：类、接口、枚举、数组等。</li></ol><p>变量在使用前必须①先声明，然后②初始化：</p><p>①声明变量：<em><strong>*类型名 变量名;*</strong></em></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int number;</span></span></code></pre></div><p>②变量的初始化就是给变量赋初值：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>number = 100;</span></span></code></pre></div><p>③可以在声明的同时初始化变量：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int number = 100;</span></span></code></pre></div><p><em><strong>*变量作用域*</strong></em></p><p><em><strong>*常量*</strong></em></p><h2 id="关键字与标识符" tabindex="-1">关键字与标识符 <a class="header-anchor" href="#关键字与标识符" aria-label="Permalink to &quot;关键字与标识符&quot;">​</a></h2><h4 id="标识符" tabindex="-1">标识符 <a class="header-anchor" href="#标识符" aria-label="Permalink to &quot;标识符&quot;">​</a></h4><p>identifier，为****变量*<em><strong>、</strong></em>*方法*<em><strong>和</strong></em>*类****进行命名</p><p>命名规则：</p><ul><li>以<code>A-Za-z</code>、<code>_</code> 或 <code>$</code> 开头，后可接<code>A-Za-z</code>、<code>_</code> 或 <code>$</code> 或<code>0-9</code>，长度无限制，例：<code>intTest, Manager_Name, _var, $Var, STATUS</code></li><li>区分大小写</li><li>关键字排除、保留字排除</li></ul><p>命名规范：</p><ul><li>见名知意，状态名词、动宾短语</li><li>驼峰模式：大驼峰、小驼峰</li></ul><p>命名风格（多单词）：</p><ul><li>PascalCase，每个单词的首字母大写。<em><strong>*类*</strong></em>、****接口****用该方法命名</li><li>camelCase，第一个单词的首字母小写，其余单词的首字母大写，<em><strong>*变量*</strong></em>、****方法****用该方法命名</li></ul><h4 id="关键字" tabindex="-1">关键字 <a class="header-anchor" href="#关键字" aria-label="Permalink to &quot;关键字&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>abstract    continue    for            new            switch</span></span>
<span class="line"><span>assert        default        goto*        package        synchronized</span></span>
<span class="line"><span>boolean        do            if            private        this</span></span>
<span class="line"><span>break        double        implements    protected    throw</span></span>
<span class="line"><span>byte        else        import        public        throws</span></span>
<span class="line"><span>case        enum        instanceof    return        transient</span></span>
<span class="line"><span>catch        extends        int            short        try</span></span>
<span class="line"><span>char        final        interface    static        void</span></span>
<span class="line"><span>class        finally        long        strictfp    volatile</span></span>
<span class="line"><span>const*        float        native        super        while</span></span>
<span class="line"><span>// 访问控制</span></span>
<span class="line"><span>private    私有的</span></span>
<span class="line"><span>protected  受保护的</span></span>
<span class="line"><span>public     公共的</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 类、方法和变量修饰符        </span></span>
<span class="line"><span>abstract        声明抽象</span></span>
<span class="line"><span>class           类</span></span>
<span class="line"><span>extends         扩充、继承</span></span>
<span class="line"><span>final           最终值、不可改变的</span></span>
<span class="line"><span>implements      实现（接口）</span></span>
<span class="line"><span>interface       接口</span></span>
<span class="line"><span>default         默认方法</span></span>
<span class="line"><span>native          本地、原生方法（非 Java 实现）</span></span>
<span class="line"><span>new             创建</span></span>
<span class="line"><span>static          静态</span></span>
<span class="line"><span>strictfp        严格浮点、精准浮点</span></span>
<span class="line"><span>synchronized    线程、同步</span></span>
<span class="line"><span>transient       短暂</span></span>
<span class="line"><span>volatile        易失</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 程序控制语句        </span></span>
<span class="line"><span>break         跳出循环</span></span>
<span class="line"><span>case          定义一个值以供</span></span>
<span class="line"><span>switch        选择</span></span>
<span class="line"><span>continue      继续</span></span>
<span class="line"><span>do            运行</span></span>
<span class="line"><span>else          否则</span></span>
<span class="line"><span>for           循环</span></span>
<span class="line"><span>if            如果</span></span>
<span class="line"><span>instanceof    实例</span></span>
<span class="line"><span>return        返回</span></span>
<span class="line"><span>switch        根据值选择执行</span></span>
<span class="line"><span>while        循环</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 错误处理        </span></span>
<span class="line"><span>assert     断言表达式是否为真</span></span>
<span class="line"><span>catch      捕捉异常</span></span>
<span class="line"><span>finally    有没有异常都执行</span></span>
<span class="line"><span>throw      抛出一个异常对象</span></span>
<span class="line"><span>throws     声明一个异常可能被抛出</span></span>
<span class="line"><span>try        捕获异常</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 包相关        </span></span>
<span class="line"><span>import     引入</span></span>
<span class="line"><span>package    包</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 基本数据类型(8种)</span></span>
<span class="line"><span>boolean    布尔型</span></span>
<span class="line"><span>byte       字节型</span></span>
<span class="line"><span>char       字符型</span></span>
<span class="line"><span>double     双精度浮点</span></span>
<span class="line"><span>float      单精度浮点</span></span>
<span class="line"><span>int        整型</span></span>
<span class="line"><span>long       长整型</span></span>
<span class="line"><span>short      短整型</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 变量引用        </span></span>
<span class="line"><span>super      父类、超类、基类</span></span>
<span class="line"><span>this       本类、子类、派生类</span></span>
<span class="line"><span>void       无返回值</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 保留关键字        </span></span>
<span class="line"><span>goto       是关键字，但不能使用</span></span>
<span class="line"><span>const      是关键字，但不能使用</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// null 不是关键字，是字面值常量，类似 true 和 false</span></span></code></pre></div><h2 id="数据类型" tabindex="-1">数据类型 <a class="header-anchor" href="#数据类型" aria-label="Permalink to &quot;数据类型&quot;">​</a></h2><p><img src="http://www.kdocs.?" alt="img"></p><h4 id="字面值" tabindex="-1">字面值 <a class="header-anchor" href="#字面值" aria-label="Permalink to &quot;字面值&quot;">​</a></h4><p>字面值（literals）是某种类型值的表示形式，比如，100是int型字面值。</p><table tabindex="0"><thead><tr><th>字面值类型</th><th>解释</th><th>示例</th></tr></thead><tbody><tr><td>基本类型字面值</td><td>基本类型的值的表示</td><td>123，3.456，true，false，&#39;g&#39;</td></tr><tr><td>字符串字面值</td><td>用双引号定界的字符序列</td><td>&quot;Hello World&quot;</td></tr><tr><td>null字面值</td><td>引用类型的空字面值</td><td>null</td></tr><tr><td>转义字面量</td><td></td><td><code>\\t \\n</code></td></tr></tbody></table><p>char类型字面值必须用单引号引一个字符，不能为空</p><p>String类型字面值用双引号，内容可有可无</p><h4 id="整数类型" tabindex="-1">整数类型 <a class="header-anchor" href="#整数类型" aria-label="Permalink to &quot;整数类型&quot;">​</a></h4><p>存储原理、进制转换、反码存储、进制转换、</p><table tabindex="0"><thead><tr><th>数据类型</th><th>所占字节数</th><th>所占位数</th><th>取值范围</th></tr></thead><tbody><tr><td>byte</td><td>1</td><td>8</td><td>-27~27-1（-128~127）</td></tr><tr><td>short</td><td>2</td><td>16</td><td>-215~215-1（-32768~32767）</td></tr><tr><td>int</td><td>4</td><td>32</td><td>-231~231-1（-2147483648~2147483647) 21亿</td></tr><tr><td>long</td><td>8</td><td>64</td><td>-263~263-1（-9223372036854775808~9223372036854775807）19位数</td></tr></tbody></table><p>整型字面值类型：</p><ol><li>十进制数，</li><li>二进制数，以<code>0b</code>或<code>0B</code>开头</li><li>八进制数，以<code>0</code>开头</li><li>十六进制数，以<code>0x</code>或<code>0X</code>开头</li></ol><h4 id="浮点数类型" tabindex="-1">浮点数类型 <a class="header-anchor" href="#浮点数类型" aria-label="Permalink to &quot;浮点数类型&quot;">​</a></h4><table tabindex="0"><thead><tr><th>数据类型</th><th>所占字节数</th><th>所占位数</th><th>取值范围</th></tr></thead><tbody><tr><td>float</td><td>4</td><td>32</td><td>-3.40E+38 ~ +3.40E+38</td></tr><tr><td>double</td><td>8</td><td>64</td><td>-1.79E+308 ~ +1.79E+308</td></tr></tbody></table><p>浮点型字面值表示方法：</p><ol><li>十进制数形式，例：3.14</li><li>科学计数法形式，例：4.5e+3</li></ol><p><em><em><em>*</em>*注意**</em>*</em><em>：浮点数的运算是不精确的，不适合做</em>***<em>*财务金融**</em>*<strong>计算，若需要精确无误的浮点计算，可以使用</strong>**<em>*BigDecimal**</em>***类。</p><p>*<em><em>*</em>*下划线**</em>***可以用在浮点型数和整型数（包括二进制、八进制、十六进制和十进制）的表示中，以增强代码可读性。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>long a = 1237_519_803L;</span></span>
<span class="line"><span>double d = 12.37_519_803d;</span></span></code></pre></div><h4 id="字符类型" tabindex="-1">字符类型 <a class="header-anchor" href="#字符类型" aria-label="Permalink to &quot;字符类型&quot;">​</a></h4><p>****字符****是程序中可以出现的任何单个符号。</p><p>Java使用Unicode为字符编码，Unicode字符集使用****两个字节（16位）****为字符编码，可表示65 536个字符。</p><p>字面值用****单引号*<em><strong>将字符括起来，大多数可见的字符都可用这种方式表示，如</strong></em>*&#39;a&#39;、&#39;@&#39;、&#39;我&#39;****等。</p><p>有些特殊字符用****转义序列****来表示。用反斜杠（\\）表示转义，如&#39;\\n&#39;表示换行。</p><table tabindex="0"><thead><tr><th>转义字符</th><th>说明</th><th>转义字符</th><th>说明</th></tr></thead><tbody><tr><td><code>\\&#39;</code></td><td>单引号字符</td><td><code>\\b</code></td><td>退格</td></tr><tr><td><code>\\&quot;</code></td><td>双引号字符</td><td><code>\\r</code></td><td>回车</td></tr><tr><td><code>\\\\</code></td><td>反斜杠字符</td><td><code>\\n</code></td><td>换行</td></tr><tr><td><code>\\f</code></td><td>换页</td><td><code>\\t</code></td><td>水平制表符</td></tr><tr><td><code>\\ddd</code></td><td>3位八进制数表示的字符</td><td><code>\\uxxx</code></td><td>4位十六进制数表示的字符</td></tr></tbody></table><h4 id="布尔类型" tabindex="-1">布尔类型 <a class="header-anchor" href="#布尔类型" aria-label="Permalink to &quot;布尔类型&quot;">​</a></h4><p>布尔型字面值很简单，只有两个值true和false，分别用来表示逻辑真和逻辑假。</p><p>布尔型值使用boolean关键字声明。</p><h4 id="字符串类型" tabindex="-1">字符串类型 <a class="header-anchor" href="#字符串类型" aria-label="Permalink to &quot;字符串类型&quot;">​</a></h4><p>Java程序中经常要使用字符串。字符串是字符序列，不属于基本数据类型，是一种引用类型。</p><p>字符串是通过String类实现的。可用String声明和创建一个字符串。可以通过双引号定界符创建一个字符串字面值。</p><h2 id="运算符" tabindex="-1">运算符 <a class="header-anchor" href="#运算符" aria-label="Permalink to &quot;运算符&quot;">​</a></h2><p>顾名思义，表示运算的符号就是运算符。参与运算的数据称为操作数。</p><h3 id="按操作数个数分类" tabindex="-1">按操作数个数分类 <a class="header-anchor" href="#按操作数个数分类" aria-label="Permalink to &quot;按操作数个数分类&quot;">​</a></h3><table tabindex="0"><thead><tr><th>运算符</th><th>所需运算符个数</th><th>示例</th></tr></thead><tbody><tr><td>一元运算符</td><td>1</td><td><code>++a</code></td></tr><tr><td>二元运算符</td><td>2</td><td><code>a &gt; b</code></td></tr><tr><td>三元运算符</td><td>3</td><td><code>a &gt; b ? c1 : c2</code></td></tr></tbody></table><h3 id="按功能分类" tabindex="-1">按功能分类 <a class="header-anchor" href="#按功能分类" aria-label="Permalink to &quot;按功能分类&quot;">​</a></h3><table tabindex="0"><thead><tr><th>运算符</th><th></th><th></th></tr></thead><tbody><tr><td>算数运算符（9个）</td><td>一元运算符（4个）</td><td>正,负,自增,自减，<code>+ - ++ --</code></td></tr><tr><td>二元运算符（5个）</td><td>求和/拼接,求差,求积,求商,求余，<code>+ - * / %</code></td><td></td></tr><tr><td>赋值运算符</td><td>简单赋值运算符</td><td>赋值，<code>=</code></td></tr><tr><td>复合赋值运算符</td><td>\`+=，-=，*=，/=，%=，&amp;=，</td><td>=\`，自带****<em>*强转**</em>***</td></tr><tr><td>关系运算符/比较运算符</td><td>比较结果为true/false</td><td><code>&gt;，&gt;=，&lt;，&lt;=，==，!=</code></td></tr><tr><td>三元运算符</td><td><code>? :</code></td><td></td></tr><tr><td>逻辑运算符</td><td>逻辑与、逻辑或、逻辑非、逻辑异或</td><td>\`&amp;</td></tr><tr><td>短路与、短路或</td><td>\`&amp;&amp;</td><td></td></tr><tr><td>位运算符</td><td>位逻辑运算</td><td>\`&amp;</td></tr><tr><td>位移位运算</td><td><code>&lt;&lt; &gt;&gt; &gt;&gt;&gt;(无符号右移)</code></td><td></td></tr></tbody></table><p><code>+</code> : 优先进行数学运算，进行不了，则进行拼接运算</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int a = 10;</span></span>
<span class="line"><span>a = a++;</span></span>
<span class="line"><span>System.out.println(a)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>int c = 10;</span></span>
<span class="line"><span>int d = 5;</span></span>
<span class="line"><span>int rs3 = c++ + ++c - --d - ++d + 1 + c--; //26</span></span>
<span class="line"><span></span></span>
<span class="line"><span>int a = 10;</span></span>
<span class="line"><span>int b = ++a + a++;</span></span>
<span class="line"><span>int c = b-- / ++a - a++ * ++b;</span></span>
<span class="line"><span>System.out.println(a + &quot;:&quot; + b + &quot;:&quot; + c);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>int a = 10;</span></span>
<span class="line"><span>int b = ++a + a;</span></span>
<span class="line"><span>int c = a++ - a++ / b-- + a++;</span></span>
<span class="line"><span>System.out.println(a + &quot;:&quot; + b + &quot;:&quot; + c);</span></span></code></pre></div><p><em><strong>*逻辑运算符表格*</strong></em></p><table tabindex="0"><thead><tr><th><em><em><em>*</em>*A**</em>*</em>*</th><th><em><em><em>*</em>*B**</em>*</em>*</th><th><em><em><em>*</em>*A&amp;B**</em>*</em>*</th><th><em><em><em>*</em>*A|B**</em>*</em>*</th><th><em><em><em>*</em>*!A**</em>*</em>*</th><th><em><em><em>*</em>*A^B**</em>*</em>*</th><th><em><em><em>*</em>*A&amp;&amp;B**</em>*</em>*</th><th><em><em><em>*</em>*A||B**</em>*</em>*</th></tr></thead><tbody><tr><td>false</td><td>false</td><td>false</td><td>false</td><td>true</td><td>false</td><td>false</td><td>false</td></tr><tr><td>false</td><td>true</td><td>false</td><td>true</td><td>true</td><td>true</td><td>false</td><td>true</td></tr><tr><td>true</td><td>false</td><td>false</td><td>true</td><td>false</td><td>true</td><td>false</td><td>true</td></tr><tr><td>true</td><td>true</td><td>true</td><td>true</td><td>false</td><td>false</td><td>true</td><td>true</td></tr></tbody></table><p>短路：在运算时先根据第一个操作数进行判断，如果从第一个操作数推退出结果，那么就不回去计算第二个操作数</p><p>短路与：A为true时才计算B</p><p>短路或：A为false时才计算B</p><p><em><em><em>*</em>*是否使用短路运算，取决于是否想让两边的表达式都执行**</em>*</em>*</p><p><em><strong>*位运算符表格*</strong></em></p><table tabindex="0"><thead><tr><th>A</th><th>B</th><th>~A</th><th>A&amp;B</th><th>A|B</th><th>A^B</th></tr></thead><tbody><tr><td>0</td><td>0</td><td>1</td><td>0</td><td>0</td><td>0</td></tr><tr><td>0</td><td>1</td><td>1</td><td>0</td><td>1</td><td>1</td></tr><tr><td>1</td><td>0</td><td>0</td><td>0</td><td>1</td><td>1</td></tr><tr><td>1</td><td>1</td><td>0</td><td>1</td><td>1</td><td>0</td></tr></tbody></table><h3 id="运算符优先级" tabindex="-1">运算符优先级 <a class="header-anchor" href="#运算符优先级" aria-label="Permalink to &quot;运算符优先级&quot;">​</a></h3><p>表达式中****出现多个运算符*<em><strong>而又</strong></em>*没有用括号****分隔时，先运算哪个后运算哪个。</p><h3 id="运算符结合性" tabindex="-1">运算符结合性 <a class="header-anchor" href="#运算符结合性" aria-label="Permalink to &quot;运算符结合性&quot;">​</a></h3><p>对于同一优先级的运算符，在表达式中与操作数的结合顺序。</p><p>左结合：运算符优先结合左边的操作数。例：a+b+c，加号优先结合操作数a</p><p>右结合：运算符优先结合右边的操作数。例：a+=b+=c，+=优先结合操作数c</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>double a = 10;</span></span>
<span class="line"><span>double b = 1, c = 2, d = 0.5;</span></span>
<span class="line"><span>System.out.println(a /= b /= c /= 0.5); // 40</span></span></code></pre></div><h2 id="表达式" tabindex="-1">表达式 <a class="header-anchor" href="#表达式" aria-label="Permalink to &quot;表达式&quot;">​</a></h2><p>由运算符和操作数组成。</p><p>表达式经过运算会产生确定的值。</p><h2 id="数据类型转换" tabindex="-1">数据类型转换 <a class="header-anchor" href="#数据类型转换" aria-label="Permalink to &quot;数据类型转换&quot;">​</a></h2><p>背景：不同数据类型直接的混合运算。</p><p>要点：计算机中数值的存储方式是补码。</p><h3 id="自动类型转换" tabindex="-1">自动类型转换 <a class="header-anchor" href="#自动类型转换" aria-label="Permalink to &quot;自动类型转换&quot;">​</a></h3><p>又称加宽转换，指将具有较少位数的数据类型转换为具有较多位数的数据类型。</p><p><img src="http://www.kdocs.?" alt="img"></p><p>表达式的最终结果类型由表达式中的****最高类型****决定。</p><p>在表达式中，<em><strong>*byte、short、char*</strong></em> 是直接转换成****int****类型参与运算的。</p><p>byte、short、char参数学运算自动提升为int，</p><h3 id="强制类型转换" tabindex="-1">强制类型转换 <a class="header-anchor" href="#强制类型转换" aria-label="Permalink to &quot;强制类型转换&quot;">​</a></h3><p>与自动类型转换相反，指将具有较多位数的数据类型转换为具有较少位数的数据类型。</p><p><em><strong>*赋值运算符（+=、-=、...）*</strong></em>、<em><strong>*自增自减运算符(++、--)*</strong></em>，自带强制类型转换</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>double d = 200.5;</span></span>
<span class="line"><span>byte b = (byte)d;    // 强制类型转换</span></span>
<span class="line"><span>System.out.println(b);     // 输出-56</span></span>
<span class="line"><span>// 00000000 00000000 00000000 110001000</span></span>
<span class="line"><span>// 11001000</span></span></code></pre></div><h3 id="表达式类型提升" tabindex="-1">表达式类型提升 <a class="header-anchor" href="#表达式类型提升" aria-label="Permalink to &quot;表达式类型提升&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>byte aa = 40;</span></span>
<span class="line"><span>byte bb = 50;</span></span>
<span class="line"><span>byte cc = a + b;             // 编译错误：不兼容的类型: 从int转换到byte可能会有损失</span></span>
<span class="line"><span>cc = (byte) (a + b);          // 正确</span></span>
<span class="line"><span>int ii = a + b;                // 正确</span></span></code></pre></div><h2 id="输入输出" tabindex="-1">输入输出 <a class="header-anchor" href="#输入输出" aria-label="Permalink to &quot;输入输出&quot;">​</a></h2><p>输出： <code>System.out.println()</code></p><p>输入：<code>new Scanner(source).nextXXX()</code></p><h2 id="小试牛刀" tabindex="-1">小试牛刀 <a class="header-anchor" href="#小试牛刀" aria-label="Permalink to &quot;小试牛刀&quot;">​</a></h2><ol><li>使用Java语言打印你的姓名和年龄。</li><li>一辆汽车的平均油耗8L/100km，每升汽油8.47元，开车自家从北京到上海大约需要多少钱？</li><li>编写程序，要求用户从键盘输入一个double型数，输出该数的整数部分和小数部分。</li><li>表达式25/4的结果是多少？如果希望得到浮点数结果，如何重写表达式？</li><li>如何用最有效的方法计算22乘以8等于多少？</li><li>编写程序，从键盘上输入一个double型的华氏温度，然后将其转换为摄氏温度输出。转换公式如下：摄氏度 = (5/9)×（华氏度-32）</li><li>编写程序，从键盘上输入你的体重（单位：公斤）和身高（单位：米），计算你的身体质量指数（Body Mass Index，BMI），该值是衡量一个人是否超重的指标。计算公式为：BMI = 体重 / 身高的平方</li></ol>`,180)])])}const V=n(i,[["render",o]]);export{g as __pageData,V as default};
